#!/usr/bin/python3

#==========================================================================================#
#
# CODE DESCRIPTION:
#
# This code processes the gradient files generated by the
# QNDM and DM methods. This code produces:
#
# - pauli_mean_dm.txt     : value N_ps and the mean for the DM method
# - pauli_mean_qndm.txt   : value N_ps and the mean for the QNDM method
# - pauli_variance_dm.txt : value N_ps and the variance for the DM method
# - pauli_variance_dm.txt : value Nl_ps and the variance for the QNDM method
# - bias_dm.txt           : value N_ps and the bias for the DM method
# - bias_qndm.txt         : value N_ps and the bias for the QNDM method
# - var_dm.txt            : value N_ps and the variance for the DM method
# - var_qndm.txt          : value N_ps and the variance for the QNDM method
# - oom_dm.txt            : value N_ps and the order of magnitude for the DM method
# - oom_qndm.txt          : value N_ps and the order of magnitude for the QNDM method
#
# In the folder structure, this code works at the lowest level of the tree.
#
#==========================================================================================#

# 
# IMPORTATION OF LIBRARIES
#----------------------------------------------------------#

import os
import sys
import numpy as np
import matplotlib.pyplot as plt


#==========================================================#
#
# FInd the valid directories containing the set_X folders
# excluding the hamiltonians (MUST be excluded)
#
#==========================================================#

def find_valid_directories(base_dir):
    valid_dirs = []
    for root, dirs, _ in os.walk(base_dir):
        if "hamiltonians" in root:
            continue  # Salta la cartella hamiltonians
        
        # Controlla se esiste almeno una cartella che inizia con "set_"
        set_dirs = [d for d in dirs if d.startswith("set_")]
        for set_dir in set_dirs:
            valid_dirs.append(os.path.join(root, set_dir))
    
    return valid_dirs


#==========================================================#
#
# Legge le colonne di un file .txt (tipo quello dei gradienti) 
# e le converte in array. THere are both the codes for the
# first and the second column.
#
#==========================================================#

def read_first_column(file_path, has_header=True):
    """
    Legge la prima colonna di un file di testo, ignorando l'eventuale intestazione e righe non numeriche.
    Restituisce un array numpy con i numeri letti.
    """
    with open(file_path, 'r') as f:
        lines = f.readlines()
    
    # Se c'è un'intestazione, rimuovila
    if has_header:
        lines = lines[1:]

    # Converti le righe in numeri, saltando quelle non valide
    data = []
    for line in lines:
        parts = line.split()
        if parts:  # Controlla che la riga non sia vuota
            try:
                data.append(float(parts[0]))  # Prova a convertire la prima colonna in float
            except ValueError:
                print(f"Attenzione: riga ignorata in {file_path}: {line.strip()}")  # Debugging
                continue  # Salta la riga se non è numerica
    
    return np.array(data)


def read_second_column(file_path, has_header=True):
    """
    Legge la seconda colonna di un file di testo, ignorando l'eventuale intestazione e righe non numeriche.
    Restituisce un array numpy con i numeri letti.
    """
    with open(file_path, 'r') as f:
        lines = f.readlines()
    
    # Se c'è un'intestazione, rimuovila
    if has_header:
        lines = lines[1:]
    
    # Converti le righe in numeri, saltando quelle non valide
    data = []
    for line in lines:
        parts = line.split()  # Suddivide la riga in parti (separate da spazi)
        if len(parts) >= 2:  # Controlla che ci siano almeno due colonne nella riga
            try:
                data.append(float(parts[1]))  # Prova a convertire la seconda colonna in float
            except ValueError:
                print(f"Attenzione: riga ignorata in {file_path}: {line.strip()}")  # Debugging
                continue  # Salta la riga se non è numerica
    
    return np.array(data)

#==========================================================#
#
# calculate_means_and_vars function. This function calculates
# the means and the variances of the gradients for the DM and
# QNDM methods. The results are saved in the corresponding
# files.
#
#==========================================================#

def calculate_means_and_vars(root_dir):
    for folder_path, _, filenames in os.walk(root_dir):
        if "hamiltonians" in folder_path:
            continue  # Salta la cartella hamiltonians
        
        # Trova il numero di Pauli strings dal percorso
        num_pauli_strings = None
        for part in folder_path.split(os.sep):
            if part.endswith("_pauli_strings"):
                num_pauli_strings = part.split("_")[0]  # Prendi solo il numero
                break
        
        if num_pauli_strings is None:
            continue  # Se non c'è il numero di Pauli strings, salta la cartella

        dm_gradients   = []
        qndm_gradients = []

        # Scan the files in the folder
        for filename in filenames:
            file_path = os.path.join(folder_path, filename)
            if filename.startswith("gradient_dm_shots_") and filename.endswith(".txt"):
                dm_gradients.append(np.loadtxt(file_path, skiprows=1))
            elif filename.startswith("gradient_qndm_shots_") and filename.endswith(".txt"):
                qndm_gradients.append(np.loadtxt(file_path, skiprows=1))
        
        # Calcola media e varianza per ogni componente del gradiente se ci sono dati
        if dm_gradients:
            dm_gradients = np.array(dm_gradients)
            dm_means     = np.mean(dm_gradients, axis=0)
            dm_vars      = np.var(dm_gradients, axis=0)
            np.savetxt(os.path.join(folder_path, "mean_gradient_dm.txt"), np.column_stack((dm_means, dm_vars)), header="mean variance")
        else:
            dm_means, dm_vars = None, None
        
        if qndm_gradients:
            qndm_gradients = np.array(qndm_gradients)
            qndm_means     = np.mean(qndm_gradients, axis=0)
            qndm_vars      = np.var(qndm_gradients, axis=0)
            np.savetxt(os.path.join(folder_path, "mean_gradient_qndm.txt"), np.column_stack((qndm_means, qndm_vars)), header="mean variance")
        else:
            qndm_means, qndm_vars = None, None
        
        # Calcola la media della media per ciascuno
        mean_mean_dm   = np.mean(dm_means)   if dm_means   is not None else 0
        mean_mean_qndm = np.mean(qndm_means) if qndm_means is not None else 0

        # Calcola la varianza media
        mean_var_dm   = np.mean(dm_vars)   if dm_vars   is not None else 0
        mean_var_qndm = np.mean(qndm_vars) if qndm_vars is not None else 0
        
        # Scrivi i risultati nei file corrispondenti
        with open(os.path.join(folder_path, "pauli_mean_dm.txt"), "w") as f:
            f.write("Num_Pauli_Strings\tMean_Mean\n")
            f.write(f"{num_pauli_strings}\t{mean_mean_dm}\n")

        with open(os.path.join(folder_path, "pauli_mean_qndm.txt"), "w") as f:
            f.write("Num_Pauli_Strings\tMean_Mean\n")
            f.write(f"{num_pauli_strings}\t{mean_mean_qndm}\n")

        with open(os.path.join(folder_path, "pauli_variance_dm.txt"), "w") as f:
            f.write("Num_Pauli_Strings\tMean_Variance\n")
            f.write(f"{num_pauli_strings}\t{mean_var_dm}\n")

        with open(os.path.join(folder_path, "pauli_variance_qndm.txt"), "w") as f:
            f.write("Num_Pauli_Strings\tMean_Variance\n")
            f.write(f"{num_pauli_strings}\t{mean_var_qndm}\n")
    
    return (dm_means, dm_vars), (qndm_means, qndm_vars)
