#==========================================================#
#
# BIAS AND ORDER OF MAGNITUDE CALCULATION
#
#==========================================================#

def calculate_bias_and_oom(root_dir):
    """
    Check the directory and calculate the differences between the gradients and the mean values of the components in modulus.
    """

    set_means = {}  # Dictionary to store the mean square of the differences
    bias_dm   = {}  # Bias for dm
    bias_qndm = {}  # Bias for qndm
    oom_dm    = {}  # Order of magnitude for dm
    oom_qndm  = {}  # Order of magnitude for qndm
    oom_sv    = {}  # Order of magnitude for sv
    var_dm    = {}  # Variance for dm
    var_qndm  = {}  # Variance for qndm

    for dirpath, _, filenames in os.walk(root_dir):
        if "hamiltonians" in dirpath:
            continue

        if {"mean_gradient_dm.txt", "mean_gradient_qndm.txt", "gradient_dm_statevector.txt", "pauli_variance_dm.txt", "pauli_variance_qndm.txt"}.issubset(filenames):
            
            sv_path       = os.path.join(dirpath, "gradient_dm_statevector.txt")

            dm_path       = os.path.join(dirpath, "mean_gradient_dm.txt")
            qndm_path     = os.path.join(dirpath, "mean_gradient_qndm.txt")
            var_dm_path   = os.path.join(dirpath, "mean_gradient_dm.txt")
            var_qndm_path = os.path.join(dirpath, "mean_gradient_qndm.txt")

            dm_data       = read_first_column(dm_path, has_header=True)
            qndm_data     = read_first_column(qndm_path, has_header=True)
            sv_data       = read_first_column(sv_path, has_header=True)
            var_dm_data   = read_second_column(var_dm_path, has_header=True)
            var_qndm_data = read_second_column(var_qndm_path, has_header=True)

            # Check for empty files
            if dm_data.size == 0 or qndm_data.size == 0 or sv_data.size == 0 or var_dm_data.size == 0 or var_qndm_data.size == 0:
                print(f"Error: one or more files in {dirpath} is empty or not legible.")
                continue

            assert len(dm_data) == len(qndm_data) == len(sv_data) == len(var_dm_data) == len(var_qndm_data), "Error: the number of elements in the files is different."
            min_len = min(len(dm_data), len(qndm_data), len(sv_data))
            dm_data, qndm_data, sv_data, var_dm_data, var_qndm_data = dm_data[:min_len], qndm_data[:min_len], sv_data[:min_len], var_dm_data[:min_len], var_qndm_data[:min_len]

            diff_dm_qndm = dm_data   - qndm_data
            diff_dm_sv   = dm_data   - sv_data
            diff_qndm_sv = qndm_data - sv_data

            np.savetxt(os.path.join(dirpath, "gradient_diff_dm_and_qndm.txt"), diff_dm_qndm)
            np.savetxt(os.path.join(dirpath, "gradient_diff_dm_and_sv.txt")  , diff_dm_sv)
            np.savetxt(os.path.join(dirpath, "gradient_diff_qndm_and_sv.txt"), diff_qndm_sv)

            # Extract the number of Pauli strings from the directory name
            set_name = os.path.basename(dirpath)
            N_ps = int(''.join(filter(str.isdigit, set_name)))

            # Calculate the mean square of the differences 
            mean_square_dm_qndm = np.mean(diff_dm_qndm**2)  # mean square of the differences between dm and qndm
            mean_square_dm_sv   = np.mean(diff_dm_sv**2)    # mean square of the differences between dm and sv
            mean_square_qndm_sv = np.mean(diff_qndm_sv**2)  # mean square of the differences between qndm and sv

            set_means[N_ps] = (mean_square_dm_qndm, mean_square_dm_sv, mean_square_qndm_sv)
            bias_dm[N_ps]   = mean_square_dm_sv
            bias_qndm[N_ps] = mean_square_qndm_sv

            # Calculate the order of magnitude (mean absolute value)
            oom_dm[N_ps]   = np.mean(np.abs(dm_data))
            oom_qndm[N_ps] = np.mean(np.abs(qndm_data))
            oom_sv[N_ps]   = np.mean(np.abs(sv_data))

            # Calculate variance mean values
            var_dm[N_ps]   = np.mean(var_dm_data)
            var_qndm[N_ps] = np.mean(var_qndm_data)

    if not set_means:
        print("No found 'set_' in the directory. Exiting...")
        return

    sorted_N_ps = sorted(set_means.keys())

    bias_dm_content   = "N_ps\tBias\n"
    bias_qndm_content = "N_ps\tBias\n"
    oom_dm_content    = "N_ps\tOoM\n"
    oom_qndm_content  = "N_ps\tOoM\n"
    oom_sv_content    = "N_ps\tOoM\n"
    var_dm_content    = "N_ps\tVariance\n"
    var_qndm_content  = "N_ps\tVariance\n"
    mse_dm_content    = "N_ps\tMSE\n"
    mse_qndm_content  = "N_ps\tMSE\n"

    for N_ps in sorted_N_ps:
        bias_val_dm   = bias_dm.get(N_ps, 0)
        bias_val_qndm = bias_qndm.get(N_ps, 0)
        var_val_dm    = var_dm.get(N_ps, 0)
        var_val_qndm  = var_qndm.get(N_ps, 0)

        mse_dm   = bias_val_dm   + var_val_dm
        mse_qndm = bias_val_qndm + var_val_qndm

        bias_dm_content   += f"{N_ps}\t{bias_val_dm:.6f}\n"
        bias_qndm_content += f"{N_ps}\t{bias_val_qndm:.6f}\n"
        oom_dm_content    += f"{N_ps}\t{oom_dm.get(N_ps, 0):.6f}\n"
        oom_qndm_content  += f"{N_ps}\t{oom_qndm.get(N_ps, 0):.6f}\n"
        oom_sv_content    += f"{N_ps}\t{oom_sv.get(N_ps, 0):.6f}\n"
        var_dm_content    += f"{N_ps}\t{var_val_dm:.6f}\n"
        var_qndm_content  += f"{N_ps}\t{var_val_qndm:.6f}\n"
        mse_dm_content    += f"{N_ps}\t{mse_dm:.6f}\n"
        mse_qndm_content  += f"{N_ps}\t{mse_qndm:.6f}\n"

    # Saving into files
    with open(os.path.join(root_dir, "bias_dm.txt"), "w") as f:
        f.write(bias_dm_content)

    with open(os.path.join(root_dir, "bias_qndm.txt"), "w") as f:
        f.write(bias_qndm_content)

    with open(os.path.join(root_dir, "oom_dm.txt"), "w") as f:
        f.write(oom_dm_content)

    with open(os.path.join(root_dir, "oom_qndm.txt"), "w") as f:
        f.write(oom_qndm_content)

    with open(os.path.join(root_dir, "oom_sv.txt"), "w") as f:
        f.write(oom_sv_content)

    with open(os.path.join(root_dir, "var_dm.txt"), "w") as f:
        f.write(var_dm_content)

    with open(os.path.join(root_dir, "var_qndm.txt"), "w") as f:
        f.write(var_qndm_content)

    with open(os.path.join(root_dir, "MSE_dm.txt"), "w") as f:
        f.write(mse_dm_content)

    with open(os.path.join(root_dir, "MSE_qndm.txt"), "w") as f:
        f.write(mse_qndm_content)

    print("All data saved.")

    


